            required
            minLength={5}
            maxLength={5}
            placeholder="Inserisci l'autore del libro"
          />
        </div>

        <div>
          <label className="block text-gray-5 5 mb-5 5 font-bold">Stato *</label>
          <select
            value={status}
            onChange={(e) => setStatus(e.target.value)}
